def is_valid_css_hsl_string(s):
    import re
    m = re.fullmatch(r'hsl\((\d{1,3}), (\d{1,3})%, (\d{1,3})%\)', s)
    if not m:
        return False
    h, sat, lig = m.groups()
    for part in (h, sat, lig):
        if len(part) > 1 and part[0] == '0':
            return False
    if int(h) > 360 or int(sat) > 100 or int(lig) > 100:
        return False
    return True

def earlier_time(t1, t2):
    def to_min(t):
        h, m = t.split(':')
        return int(h)*60 + int(m)
    return t1 if to_min(t1) <= to_min(t2) else t2

def is_balanced_within_depth(s, limit):
    pairs = {')': '(', ']': '[', '}': '{'}
    opens = set(pairs.values())
    stack = []
    depth = 0
    max_depth = 0
    for c in s:
        if c in opens:
            stack.append(c)
            depth += 1
            max_depth = max(max_depth, depth)
        elif c in pairs:
            if not stack or stack.pop() != pairs[c]:
                return False
            depth -= 1
        else:
            return False
    return not stack and max_depth <= limit

