    a = 0
    for k in range(1, n + 1):
        prev = a - k
        if prev > 0 and prev not in seen:
            a = prev
        else:
            a = a + k
        seen.add(a)
    return a

def remove_first_and_last_occurrence(s, ch):
    first = s.find(ch)
    if first == -1:
        return s
    last = s.rfind(ch)
    if first == last:
        return s[:first] + s[first + 1:]
    chars = list(s)
    del chars[last]
    del chars[first]
    return "".join(chars)

def truncate_ellipsis(s, maxlen):
    if len(s) <= maxlen:
        return s
    if maxlen <= 3:
        return s[:maxlen]
    return s[:maxlen - 3] + '...'

def sort_by_reversed_digits_value(nums):
    def rev(n):
        return int(str(abs(n))[::-1])
    return sorted(nums, key=lambda n: (rev(n), n))

