def longest_run_below_threshold(lst, t):
    best = 0
    cur = 0
    for x in lst:
        if x < t:
            cur += 1
            best = max(best, cur)
        else:
            cur = 0
    return best

def lookup_chain(d, keys):
    cur = d
    for k in keys:
        if isinstance(cur, dict) and k in cur:
            cur = cur[k]
        else:
            return None
    return cur

def is_balanced_angle_brackets(s):
    depth = 0
    for c in s:
        if c == '<':
            depth += 1
        elif c == '>':
            depth -= 1
            if depth < 0:
                return False
        else:
            return False
    return depth == 0

