def render_row_mixed(cells, widths, aligns):
    parts = []
    for c, w, a in zip(cells, widths, aligns):
        if a == 'l':
            parts.append(c.ljust(w))
        elif a == 'r':
            parts.append(c.rjust(w))
        else:
            parts.append(c.center(w))
    return " ".join(parts)

def percentile_labels_sorted(scores):
    n = len(scores)
    def pct(v):
        return round(100 * sum(1 for s in scores if s <= v) / n)
    return sorted([(v, pct(v)) for v in scores], key=lambda t: t[0])

def format_percent_change(old, new):
    if old == 0:
        return "N/A"
    value = (new - old) / old * 100
    sign = "+" if value >= 0 else "-"
    return f"{sign}{abs(value):.1f}%"

def previous_leap_year(year):
    y = year - 1
    while not (y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)):
        y -= 1
    return y

def unique_slug(base, existing):
    if base not in existing:
        return base
    i = 2
    while f"{base}-{i}" in existing:
        i += 1
    return f"{base}-{i}"

