def count_plateaus(lst):
    if not lst:
        return 0
    count = 1
    for i in range(1, len(lst)):
        if lst[i] != lst[i - 1]:
            count += 1
    return count

def find_duplicates_only(lst):
    from collections import Counter
    counts = Counter(lst)
    seen = set()
    out = []
    for x in lst:
        if counts[x] > 1 and x not in seen:
            seen.add(x)
            out.append(x)
    return out
